UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "[[q]]must[[/q]] ve [[q]]have to[[/q]] arasındaki seçim zorunluluğun KAYNAĞINA bakılarak yapılır:", "items": [{"heading": "must vs have to: Kaynağı Bul", "badge": "Zorunluluk Kaynağı", "body": [{"type": "text", "text": "[[q]]must[[/q]]: konuşmacının [[amber]]KENDİ[[/amber]] kararı/kişisel zorunluluğu (\"I must finish this today\" — kendi isteğim)."}, {"type": "text", "text": "[[q]]have to[[/q]]: [[amber]]DIŞARIDAN[[/amber]] gelen bir kural, yasa veya zorunluluk."}, {"type": "example_check", "correct": "Employees have to wear a uniform", "wrong_note": "bu şirket kuralıdır, kişisel istek değildir"}]}, {"heading": "Olumsuzda Tamamen Farklı Anlam", "is_warning": true, "warning_label": "🔥 EN SIK TUZAK", "body": [{"type": "text", "text": "Olumsuzda ikisi [[dark]]TAMAMEN FARKLI[[/dark]] anlam taşır — bu YDS'nin en sık sorduğu ayrımlardan biridir."}], "meaning_pairs": [[{"word": "must not", "meaning": "YASAK (\"You must not smoke here\")"}, {"word": "don't have to", "meaning": "GEREK YOK, yapmasan da olur", "variant": "wrong"}]], "warning_text": "\"You must not smoke here\" (yasak) ile \"You don't have to come if you're busy\" (gerek yok, istersen gel) birbirine KARIŞTIRILMAMALIDIR."}, {"heading": "should / ought to: Tavsiye", "body": [{"type": "text", "text": "[[q]]should/ought to[[/q]] ise tavsiye ve beklenti bildirir, zorunluluk değil."}, {"type": "text", "text": "Geçmişte [[q]]should have V3[[/q]] [[dark]]PİŞMANLIK[[/dark]] anlamı taşır (\"yapmalıydın ama yapmadın\")."}]}], "examples": [{"sentence": "According to the new regulation, all visitors have to wear a badge.", "answer_word": "have to", "reasoning": "Dışarıdan gelen bir kural (regulation) olduğu için doğru cevap [[right]]\"have to\"[[/right]]dur, [[wrong]]\"must\"[[/wrong]] değil. Benzer mantıkla \"You don't have to worry about the exam, it's not that hard.\" cümlesinde \"don't have to\" (gerek yok) doğruyken, \"must not\" (yasak) anlamca yanlış olurdu."}, {"sentence": "I really must call my grandmother, I haven't spoken to her in weeks.", "answer_word": "must", "reasoning": "Bu, dışarıdan gelen bir kural değil, konuşmacının kendi hissettiği kişisel bir sorumluluk olduğu için doğru cevap [[right]]\"must\"[[/right]]tur, [[wrong]]\"have to\"[[/wrong]] değil. \"You should have told me about the meeting, I missed it completely.\" cümlesinde ise geçmişte yapılmayan ve pişmanlık duyulan bir eylem anlatıldığı için doğru cevap \"should have told\" olur."}, {"sentence": "Passengers have to fasten their seatbelts whenever the illuminated sign requires it; it's a strict airline regulation.", "answer_word": "have to", "reasoning": "Zorunluluk havayolunun koyduğu DIŞARIDAN bir kuraldan geldiği için doğru cevap [[right]]\"have to\"[[/right]]dur."}, {"sentence": "You don't have to apologize for the delay — it was completely out of your control and nobody is blaming you.", "answer_word": "don't have to", "reasoning": "Burada yapılmasının GEREKMEDİĞİ ama serbest olduğu bir durum anlatılıyor → doğru cevap [[right]]\"don't have to\"[[/right]]dur; [[wrong]]\"must not\"[[/wrong]] kullanmak burada bir YASAK anlamı katar ki bu cümlenin bağlamıyla çelişir."}]}$tagbd$::jsonb WHERE id = 'e8cab074-60e8-43c1-b973-2bb9273e1c43';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "[[q]]on time[[/q]] ile [[q]]in time[[/q]] arasındaki seçim, cümlede sabit bir SAAT mi yoksa bir SONUCA yetişme mi vurgulandığına bağlıdır:", "items": [{"heading": "on time: Tam Saatinde", "badge": "Sabit Program", "body": [{"type": "text", "text": "[[q]]on time[[/q]] planlanan/beklenen [[amber]]TAM SAATTE[[/amber]] gerçekleşmeyi anlatır (geç kalmamak, programa uymak) — tren, toplantı, uçuş gibi bir ZAMAN ÇİZELGESİYLE ilişkilidir."}, {"type": "example_check", "correct": "The train left exactly on time", "wrong_note": "\"in time\" burada yanlıştır çünkü kaçırılan bir fırsat değil sabit bir saat vurgusu var"}]}, {"heading": "in time: Yetişerek, Geç Kalmadan", "badge": "Sonuca Yetişme", "body": [{"type": "text", "text": "[[q]]in time[[/q]] ise bir şey olmadan/çok geç olmadan ÖNCE yetişmeyi anlatır, genellikle [[amber]]\"for + isim\"[[/amber]] veya [[amber]]\"to + fiil\"[[/amber]] ile bir SONUÇLA birlikte kullanılır."}, {"type": "example_check", "correct": "We arrived just in time to see the newborn baby", "wrong_note": "\"on time\" burada yanlıştır çünkü sabit bir saat değil bir sonuca yetişme vurgusu var"}]}, {"heading": "Tetikleyici Kelimeler", "badge": "İpucu", "body": [{"type": "text", "text": "Cümlede sabit bir saat/program ([[amber]]\"exactly\", \"precisely\", \"punctual\"[[/amber]]) vurgusu varsa [[q]]on time[[/q]]; bir şeyi kaçırmamak/yetişmek vurgusu ([[amber]]\"just in time\", \"just... before\"[[/amber]]) varsa [[q]]in time[[/q]] doğru cevaptır."}]}], "examples": [{"sentence": "The train left exactly on time, so all the passengers who arrived a minute late missed it.", "answer_word": "on time", "reasoning": "Cümledeki [[b]]\"exactly\"[[/b]] ve belirli bir saate uyma vurgusu, sabit bir programı işaret eder → doğru cevap [[right]]\"on time\"[[/right]]dır."}, {"sentence": "We arrived at the hospital just in time to see the newborn baby before visiting hours ended.", "answer_word": "in time", "reasoning": "[[b]]\"just... before\"[[/b]] yapısı, bir şey olmadan HEMEN ÖNCE yetişmeyi anlatır, sabit bir saatten değil bir sondan bahsedilir → doğru cevap [[right]]\"in time\"[[/right]]dır."}, {"sentence": "The shipment arrived precisely on time for the scheduled unloading at 6 a.m.", "answer_word": "on time", "reasoning": "Cümledeki [[b]]\"precisely\"[[/b]] ve sabit bir SAATE (6 a.m.) bağlı program vurgusu olduğu için doğru cevap [[right]]\"on time\"[[/right]]dır; [[wrong]]\"in time\"[[/wrong]] burada yanlıştır çünkü kaçırılan bir fırsat ya da son an yetişme durumu söz konusu değildir."}, {"sentence": "She finished wrapping the last gift just in time before the guests started arriving at the door.", "answer_word": "in time", "reasoning": "[[b]]\"just... before\"[[/b]] yapısı, bir şeyin olmasından HEMEN ÖNCE yetişmeyi anlatır, sabit bir saat değil bir SONUÇ vurgulanır → doğru cevap [[right]]\"in time\"[[/right]]dır."}]}$tagbd$::jsonb WHERE id = '3fefa927-2f45-4878-a703-41ed55900621';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Daha önce geçen SAYILABİLEN bir ismin tekrarını önlemek için [[q]]one[[/q]] (tekil) / [[q]]ones[[/q]] (çoğul) kullanılır:", "items": [{"heading": "one / ones: Sayılabilir İsmin Yerini Tutar", "badge": "Tekrar Önleme", "body": [{"type": "text", "text": "Cümlede daha önce geçen SAYILABİLEN bir isim tekrar edilmeyecekse, o ismin yerine tekilse [[q]]one[[/q]], çoğulsa [[q]]ones[[/q]] kullanılır."}, {"type": "example_check", "correct": "could you show me a cheaper one?", "wrong_note": "sayılamayan isimlerin yerine \"one/ones\" KULLANILMAZ"}]}, {"heading": "Sıfatlarla Birlikte Kullanım", "body": [{"type": "text", "text": "Bu zamir SIFATLARLA birlikte kullanılabilir ([[b]]\"the red one\", \"the expensive ones\"[[/b]])."}]}, {"heading": "Ayırt Etme İpucu", "badge": "Karar Sorusu", "body": [{"type": "text", "text": "Boşluktan önce [[amber]]this/that/these/those/the/a/an + sıfat[[/amber]] gibi bir belirteç varsa ve ardından önceden bahsedilen bir isim tekrarlanacaksa [[q]]one/ones[[/q]] güçlü bir adaydır; isim sayılamıyorsa veya zamir zaten nesnenin [[b]]KENDİSİNİ[[/b]] ([[q]]it/them[[/q]]) işaret ediyorsa [[q]]one/ones[[/q]] [[bad]]yanlıştır[[/bad]]."}]}], "examples": [{"sentence": "I don't like this jacket; could you show me a cheaper one?", "answer_word": "one", "reasoning": "\"jacket\" sayılabilen, tekil bir isim ve tekrar edilmemesi gerekiyor → doğru cevap [[right]]\"one\"[[/right]]dur."}, {"sentence": "These shoes are too tight; do you have any larger ones?", "answer_word": "ones", "reasoning": "\"shoes\" çoğul olduğu için → doğru cevap [[right]]\"ones\"[[/right]]tur, [[wrong]]\"one\"[[/wrong]] tekil olduğu için burada yanlıştır."}, {"sentence": "I've already read this novel; do you have a more recent one?", "answer_word": "one", "reasoning": "\"novel\" sayılabilen, tekil bir isim olduğu ve tekrar edilmemesi gerektiği için doğru cevap [[right]]\"one\"[[/right]]dur."}, {"sentence": "The blue curtains look old-fashioned; let's buy some new ones instead.", "answer_word": "ones", "reasoning": "\"curtains\" çoğul olduğu için doğru cevap [[right]]\"ones\"[[/right]]tur; tekil [[wrong]]\"one\"[[/wrong]] burada gramer olarak uyumsuzdur."}]}$tagbd$::jsonb WHERE id = '8a5f28b6-b85d-468e-a81a-4d577ea3d36c';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "[[q]]needn't[[/q]] ile [[q]]mustn't[[/q]] arasındaki fark, bir eylemin GEREKSİZ mi yoksa YASAK mı olduğudur:", "items": [{"heading": "needn't: Gerek Yok Ama Yasak Değil", "badge": "Gereksizlik", "body": [{"type": "text", "text": "[[q]]needn't[[/q]] (= don't/doesn't need to) bir eylemin yapılmasının [[amber]]GEREKMEDİĞİNİ[[/amber]] ama yapılmasının YASAK olmadığını anlatır — kişi isterse yine de yapabilir."}, {"type": "example_check", "correct": "You needn't bring your own laptop", "wrong_note": "\"mustn't\" burada yanlıştır çünkü getirmek yasak değildir"}]}, {"heading": "mustn't: Kesinlikle Yasak", "badge": "Yasak", "body": [{"type": "text", "text": "[[q]]mustn't[[/q]] ise bir eylemin [[dark]]KESİNLİKLE YASAK[[/dark]] olduğunu, yapılmaması gerektiğini anlatır."}, {"type": "example_check", "correct": "Visitors mustn't touch the exhibits", "wrong_note": "\"needn't\" burada yanlıştır çünkü cümle sadece gereksizliği değil yasağı anlatıyor"}]}, {"heading": "İpucu Kelimeleri", "body": [{"type": "text", "text": "Cümlede [[amber]]\"it's not necessary\", \"there's no need\", \"you're free to... but\"[[/amber]] gibi ifadeler varsa [[q]]needn't[[/q]]; [[amber]]\"it's forbidden\", \"not allowed\", \"strictly prohibited\"[[/amber]] gibi ifadeler varsa [[q]]mustn't[[/q]] doğru cevaptır."}]}, {"heading": "Geçmişte: needn't have vs mustn't have", "is_warning": true, "warning_label": "🔥 EN SIK TUZAK", "body": [{"type": "text", "text": "[[q]]needn't have + V3[[/q]] yapısı, geçmişte YAPILMASI GEREKMEYEN ama YAPILMIŞ bir eylemi anlatır (gereksiz çaba)."}], "meaning_pairs": [[{"word": "needn't have + V3", "meaning": "yapılması gerekmeyen ama yapılmış bir eylem (gereksiz çaba)"}, {"word": "mustn't have + V3", "meaning": "bir şeyin yapılmamış olması gerektiğine dair çıkarım", "variant": "wrong"}]], "warning_text": "Bu ikisi birbirine KARIŞTIRILMAMALIDIR."}], "examples": [{"sentence": "You needn't bring your own laptop; the company provides one for every employee.", "answer_word": "needn't", "reasoning": "Şirketin zaten bilgisayar sağlaması, kendi laptopunu getirmenin GEREKMEDİĞİNİ (ama getirebileceğini) gösterir → doğru cevap [[right]]\"needn't\"[[/right]]tür, [[wrong]]\"mustn't\"[[/wrong]] değildir çünkü getirmek yasak değildir."}, {"sentence": "Visitors mustn't touch the exhibits; it is strictly prohibited to protect the artifacts.", "answer_word": "mustn't", "reasoning": "Cümledeki [[b]]\"strictly prohibited\"[[/b]] ifadesi kesin bir yasağı belirtir → doğru cevap [[right]]\"mustn't\"[[/right]]tür; [[wrong]]\"needn't\"[[/wrong]] burada yanlıştır çünkü sadece gereksizliği değil, yasağı anlatan bir ifade kullanılmıştır."}, {"sentence": "You needn't wait for me at the entrance; just go ahead and I'll catch up with you inside.", "answer_word": "needn't", "reasoning": "Cümlede konuşanın karşı tarafı beklemesinin GEREKMEDİĞİNİ ama isterse bekleyebileceğini anlatan serbest bir izin tonu var → doğru cevap [[right]]\"needn't\"[[/right]]tür; [[wrong]]\"mustn't\"[[/wrong]] burada yanlıştır çünkü beklemek yasak değildir, sadece gereksizdir."}, {"sentence": "Passengers mustn't use their mobile phones during takeoff and landing, as it is a strict aviation safety regulation.", "answer_word": "mustn't", "reasoning": "Cümledeki [[b]]\"strict... regulation\"[[/b]] ifadesi kesin bir yasağı belirtir → doğru cevap [[right]]\"mustn't\"[[/right]]tür; [[wrong]]\"needn't\"[[/wrong]] burada yanlıştır çünkü anlatılan şey bir gereksizlik değil, resmi bir yasaktır."}]}$tagbd$::jsonb WHERE id = 'c8de0b51-aa0d-4787-b9b2-97496126f796';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Düzensiz çoğul isimleri ezberlemek yerine üç ana kalıpta grupla:", "items": [{"heading": "Üç Düzensiz Çoğul Kalıbı", "badge": "Kalıp Tanıma", "sub_rules": [{"condition": "[[amber]]Kök değişimi yapan eski İngilizce kökenli isimler[[/amber]] (ayrıca: woman→women, child→children, foot→feet, tooth→teeth, mouse→mice, goose→geese):", "from": "man", "to": "men"}, {"condition": "[[amber]]Tekili ve çoğulu AYNI olan isimler[[/amber]] (ayrıca: deer, fish, series, aircraft):", "from": "sheep (tekil)", "to": "sheep (çoğul)"}, {"condition": "[[amber]]Latince/Yunanca kökenli akademik/bilimsel isimler[[/amber]] (-on/-um → -a, -is → -es; ayrıca: analysis→analyses, crisis→crises, datum→data):", "from": "phenomenon / criterion", "to": "phenomena / criteria"}]}, {"heading": "Özne-Yüklem Uyumu Tuzağı", "is_warning": true, "warning_label": "🔥 EN SIK TUZAK", "body": [{"type": "text", "text": "Çoğul anlam taşıyan bir isim ([[q]]criteria, phenomena, data[[/q]]) cümlede ÖZNE ise fiil de [[dark]]ÇOĞUL[[/dark]] olmalıdır."}, {"type": "example_check", "correct": "The criteria are strict", "wrong_note": "\"The criteria is strict\" ya da \"criterias\" gibi çoğul eki fazladan eklenmiş bir şık KESİNLİKLE yanlıştır"}], "warning_text": "Sınavda bu isimler genellikle özne-yüklem uyumu sorularında karşına çıkar."}], "examples": [{"sentence": "Several new species of butterfly were discovered in the rainforest last year.", "answer_word": "species", "reasoning": "\"species\" hem tekil hem çoğul olarak aynı şekilde yazılan bir isimdir ve burada çoğul anlamda kullanılmıştır → doğru cevap [[right]]\"species\"[[/right]]tir; [[bad]]\"speciess\"[[/bad]] diye bir form yoktur."}, {"sentence": "The criteria used to evaluate the candidates were published on the university's website.", "answer_word": "criteria", "reasoning": "\"criterion\"un çoğulu \"criteria\"dır ve cümledeki fiil zaten çoğul (\"were\") olduğu için özneyle uyumlu olmalı → doğru cevap [[right]]\"criteria\"[[/right]]dır; [[bad]]\"criterias\"[[/bad]] ya da tekil \"criterion\" (fiille uyumsuz) burada yanlıştır."}, {"sentence": "Several unexplained phenomena were reported by sailors in that region long before scientists offered an explanation.", "answer_word": "phenomena", "reasoning": "\"phenomenon\"un çoğulu \"phenomena\"dır ve cümledeki fiil çoğul (\"were\") olduğu için özneyle uyumlu olmalı → doğru cevap [[right]]\"phenomena\"[[/right]]dır; [[bad]]\"phenomenons\"[[/bad]] diye bir çoğul biçim yoktur."}, {"sentence": "The dentist explained that most adult teeth eventually need some form of treatment.", "answer_word": "teeth", "reasoning": "\"tooth\"un düzensiz çoğulu \"teeth\"tir; eski İngilizce kökenli isimler grubuna girer → doğru cevap [[right]]\"teeth\"[[/right]]tir; [[bad]]\"tooths\"[[/bad]] ya da \"toothes\" gibi -s ekiyle oluşturulmuş yanlış bir çoğul biçim sınavda çeldirici olarak kullanılır."}]}$tagbd$::jsonb WHERE id = '49093205-6e94-485c-98ff-b5e739afa6ae';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "[[q]]must[[/q]] ve [[q]]have to[[/q]] arasındaki seçim zorunluluğun KAYNAĞINA bakılarak yapılır:", "items": [{"heading": "must vs have to: Kaynağı Bul", "badge": "Zorunluluk Kaynağı", "body": [{"type": "text", "text": "Zorunluluk konuşmacının [[amber]]KENDİ GÖRÜŞÜNDEN[[/amber]], kişisel bir gerekliliğinden doğuyorsa [[q]]must[[/q]] kullanılır (\"I must call my mother\" — bunu ben öyle hissettiğim için yapmalıyım)."}, {"type": "text", "text": "Zorunluluk [[amber]]DIŞARIDAN[[/amber]] gelen bir kural, otorite ya da durumdan doğuyorsa [[q]]have to[[/q]] kullanılır."}, {"type": "example_check", "correct": "I have to wear a uniform at work", "wrong_note": "bu işyeri kuralıdır, kendi fikri değildir"}]}, {"heading": "Olumsuzda Anlam Tamamen Değişir", "is_warning": true, "warning_label": "🔥 EN SIK TUZAK", "body": [{"type": "text", "text": "Bu ayrım özellikle OLUMSUZ formda kritik bir anlam farkına dönüşür."}], "meaning_pairs": [[{"word": "mustn't", "meaning": "YASAK (\"You mustn't smoke here\")"}, {"word": "don't have to", "meaning": "GEREKMİYOR ama serbest (\"You don't have to come if you're busy\")", "variant": "wrong"}]], "warning_text": "Bu iki yapı YDS'de sıkça birbirine karıştırılır."}, {"heading": "Geçmiş Zamanda must Yoktur", "body": [{"type": "text", "text": "Geçmiş zamanda [[q]]must[[/q]] kullanılamaz, zorunlu olarak [[q]]had to[[/q]] kullanılır — bu YDS'nin sık sorduğu bir zaman tuzağıdır."}]}], "examples": [{"sentence": "All passengers have to fasten their seatbelts before the plane takes off — it's airline policy.", "answer_word": "have to", "reasoning": "Zorunluluk havayolu şirketinin DIŞARIDAN koyduğu bir kural olduğu için doğru cevap [[right]]\"have to\"[[/right]]dur; \"must\" burada da kabul edilebilir olsa da, kuralın kaynağı resmi bir otorite olduğu için sınavlarda \"have to\" tercih edilen cevaptır."}, {"sentence": "When I was a child, we had to finish all our homework before watching television.", "answer_word": "had to", "reasoning": "Cümle GEÇMİŞ zamanda olduğu için [[bad]]\"must\"[[/bad]] kullanılamaz, doğru cevap [[right]]\"had to\"[[/right]]dur; bu, \"must\"ın geçmiş zaman formunun bulunmadığının klasik bir test şeklidir."}, {"sentence": "I really must apologize to her — I've been feeling guilty about what I said all week.", "answer_word": "must", "reasoning": "Zorunluluk konuşmacının kendi vicdani hissinden, KİŞİSEL bir gereklilikten doğduğu için doğru cevap [[right]]\"must\"[[/right]]tur; [[wrong]]\"have to\"[[/wrong]] dışarıdan bir kural çağrıştıracağı için konuşmacının içsel pişmanlık tonunu tam yansıtmaz."}, {"sentence": "Employees have to wear safety helmets on the construction site at all times.", "answer_word": "have to", "reasoning": "Zorunluluk iş güvenliği mevzuatının DIŞARIDAN koyduğu bir kural olduğu için doğru cevap [[right]]\"have to\"[[/right]]dur; kuralın kaynağı resmi bir otorite olduğundan bu bağlamda tercih edilen ifadedir."}]}$tagbd$::jsonb WHERE id = 'd35a6f81-754a-4637-b1b1-1b8ba08f3a53';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "[[q]]can[[/q]] / [[q]]may[[/q]] / [[q]]could[[/q]] üçlüsünü ayırt ederken cümlenin bir İZİN mi yoksa bir RİCA mı olduğuna bak:", "items": [{"heading": "can: Günlük İzin", "badge": "Gayri Resmi", "body": [{"type": "text", "text": "[[q]]can[[/q]]: günlük, gayri resmi izin bildirir."}, {"type": "example_check", "correct": "You can leave early today", "wrong_note": "günlük konuşmada izin bildiren en yaygın modaldır"}]}, {"heading": "may: Resmi İzin", "badge": "Resmi", "body": [{"type": "text", "text": "[[q]]may[[/q]]: daha [[amber]]RESMİ[[/amber]] izin, özellikle soru kalıbında kibar bir izin isteme için kullanılır."}, {"type": "example_check", "correct": "May I use your phone?", "wrong_note": "resmi/akademik bağlamda izin isteme bağlamında tercih edilen biçimdir"}]}, {"heading": "could: İzin Değil, Rica", "is_warning": true, "warning_label": "🔥 EN SIK TUZAK", "body": [{"type": "text", "text": "[[q]]could[[/q]] izin DEĞİL, [[dark]]KİBAR BİR RİCA[[/dark]] bildirir."}, {"type": "example_check", "correct": "Could you explain that again?", "wrong_note": "bu izin istemiyor, rica ediyor (\"Açıklar mısınız?\")"}], "warning_text": "Bu üçü arasında en sık karıştırılan nokta [[q]]could[[/q]]'un izin değil rica işlevi görmesidir."}, {"heading": "Bağlam İpucu", "body": [{"type": "text", "text": "Resmî/akademik bir metinde izin bağlamında [[q]]may[[/q]] tercih edilir; günlük konuşma diyaloglarında [[q]]can[[/q]] daha yaygındır."}]}], "examples": [{"sentence": "Could you pass me the salt, please?", "answer_word": "Could", "reasoning": "Burada bir izin değil, kibar bir rica söz konusu → doğru cevap [[right]]\"Could\"[[/right]] (ya da \"Can\"), fakat resmi bir izin isteme bağlamında (\"May I leave the room?\") doğru seçim \"May\"dir."}, {"sentence": "May I borrow your pen for a second?", "answer_word": "May", "reasoning": "Burada resmi bir izin isteme söz konusu → doğru cevap [[right]]\"May\"[[/right]] (ya da gündelik dilde \"Can\"), ama \"Could you lower your voice, please? I'm on the phone.\" cümlesinde izin değil kibar bir rica anlatıldığı için doğru cevap [[wrong]]\"Could\"[[/wrong]] ya da \"Would\"dur; \"May\" burada garip kaçar çünkü \"May\" karşıdaki kişiden rica etmek için değil izin istemek/vermek için kullanılır."}, {"sentence": "May I use the restroom before we start the meeting?", "answer_word": "May", "reasoning": "Burada resmi bir ortamda izin isteme söz konusu → doğru cevap [[right]]\"May\"[[/right]] (ya da gündelik dilde \"Can\"); [[wrong]]\"Could\"[[/wrong]] burada da kabul edilebilir bir rica tonu katar ama \"May\" resmi izin istemenin en klasik işaretidir."}, {"sentence": "Could you hold the door for me? My hands are full.", "answer_word": "Could", "reasoning": "Burada bir izin değil, kibar bir yardım RİCASI söz konusu → doğru cevap [[right]]\"Could\"[[/right]] (ya da \"Would\"); [[wrong]]\"May\"[[/wrong]] burada garip kaçar çünkü karşı taraftan bir eylem yapmasını rica ediyoruz, izin istemiyoruz."}]}$tagbd$::jsonb WHERE id = 'dac7e7b7-d658-48cf-818f-7a4b6c25a582';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Karma (mixed) şart cümlelerinde if cümleciği ile sonuç cümleciği FARKLI zaman dilimlerine ait olabilir:", "items": [{"heading": "Tip 1: Geçmiş Koşul → Şimdiki Sonuç", "badge": "Kalıp 1", "body": [{"type": "text", "text": "GEÇMİŞTEKİ bir durumun ŞİMDİKİ sonucu: [[q]]if + PAST PERFECT[[/q]], [[q]]WOULD + fiilin yalın hâli[[/q]]."}, {"type": "example_check", "correct": "If I had taken that job, I would be living in London now", "wrong_note": "\"would have been living\" kullanmak yanlış olurdu çünkü sonuç ŞİMDİKİ zamana aittir (\"now\")"}]}, {"heading": "Tip 2: Şimdiki Durum → Geçmiş Sonuç", "badge": "Kalıp 2", "body": [{"type": "text", "text": "ŞİMDİKİ/sürekli bir durumun GEÇMİŞTEKİ sonucu: [[q]]if + PAST SIMPLE[[/q]], [[q]]WOULD HAVE + V3[[/q]]."}, {"type": "example_check", "correct": "If she weren't so shy, she would have spoken up at the meeting", "wrong_note": "kişilik özelliği hâlâ geçerli olduğu için \"if\" tarafı PAST SIMPLE olmalı, PAST PERFECT değil"}]}, {"heading": "Zaman Belirteci İpucu", "body": [{"type": "text", "text": "Bu soruları çözerken cümlede [[amber]]\"now/still\"[[/amber]] gibi şimdiki zaman belirteçleri mi, yoksa belirli bir geçmiş olay mı anlatıldığına bakarak hangi tarafın hangi zamana ait olduğunu belirle."}]}], "examples": [{"sentence": "If he were more responsible, he wouldn't have lost his job last month.", "answer_word": "were", "reasoning": "\"he\"nin genel kişilik özelliği (sorumsuzluk) ŞİMDİKİ zamanda devam eden bir durum, ama sonuç (\"işini kaybetti\") GEÇMİŞTE gerçekleşmiş → doğru cevap [[right]]\"were\"[[/right]] (if + past simple), sonuç kısmında ise \"wouldn't have lost\" (would have + V3) zaten doğru verilmiştir."}, {"sentence": "If she had accepted that job offer five years ago, she would be running her own company now.", "answer_word": "had accepted", "reasoning": "Geçmişteki bir karar (teklifi kabul etmedi) ŞİMDİKİ bir sonucu (şirketi yok) etkilediği için doğru cevap [[right]]\"had accepted\"[[/right]]tır (if + past perfect), sonuç kısmında ise \"now\" kelimesi şimdiki zamana işaret ettiği için \"would be running\" (would + yalın fiil, \"would have run\" değil) kullanılmıştır."}, {"sentence": "If they had invested in better equipment years ago, their factory would be far more productive today.", "answer_word": "had invested", "reasoning": "Geçmişteki bir karar (yatırım yapmadılar) ŞİMDİKİ bir sonucu (düşük verimlilik) etkilediği için doğru cevap [[right]]\"had invested\"[[/right]]tir (if + past perfect); sonuç kısmındaki \"today\" kelimesi şimdiki zamana işaret ettiği için \"would be\" (would + yalın fiil) kullanılmıştır, \"would have been\" değil."}, {"sentence": "If he weren't such a stubborn person, he would have accepted their help when the accident happened.", "answer_word": "weren't", "reasoning": "Kişilik özelliği (inatçılık) ŞİMDİKİ zamanda devam eden genel bir durum, ama sonuç (\"yardımı kabul etmedi\") GEÇMİŞTE gerçekleşmiş bir olay → doğru cevap [[right]]\"weren't\"[[/right]]tir; sonuç kısmında zaten doğru şekilde \"would have accepted\" (would have + V3) kullanılmıştır."}]}$tagbd$::jsonb WHERE id = 'fd48f9bb-1483-4aef-92f6-f6a1cfd26945';
